            return result;
        }

        std::vector<AnalysisResult> analyzeBatch(const std::vector<std::string>& payloads) {
            std::vector<AnalysisResult> results;
            std::vector<std::future<AnalysisResult>> futures;

            for (const auto& payload : payloads) {
                futures.emplace_back(std::async(std::launch::async,  {
                    return analyzePayload(payload);
                }));
            }

            for (auto& future : futures) {
                results.push_back(future.get());
            }

            return results;
        }

    private:
        bool matchesPatterns(const std::string& payload, const std::vector<std::regex>& patterns) {
            return std::any_of(patterns.begin(), patterns.end(), [&payload](const std::regex& pattern) {
                return std::regex_search(payload, pattern);
            });
        }
    };

